package com.doulala.android;

import com.doulala.android.video.VideoProvider;
import org.json.JSONArray;
import org.json.JSONObject;
import org.json.JSONTokener;
import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.util.*;

/** Explicit HTTPS adapter for a user-operated gateway; it is not a Dola API client. */
public final class VideoGateway implements VideoProvider {
  private static final int CONNECT_MS=15_000, READ_MS=30_000, MAX_JSON=1_048_576, MAX_DOWNLOAD=1_073_741_824;
  private final URL origin; private final String token; private final java.util.function.BooleanSupplier cancelled; private final long deadline;
  public VideoGateway(String configuredOrigin,String memoryOnlyToken) throws Exception { this(configuredOrigin,memoryOnlyToken,()->false); } public VideoGateway(String configuredOrigin,String memoryOnlyToken,java.util.function.BooleanSupplier c) throws Exception { origin=origin(configuredOrigin); token=memoryOnlyToken==null?"":memoryOnlyToken; cancelled=c==null?()->false:c; deadline=System.currentTimeMillis()+2*60*60_000L; }
  public String origin(){ return origin.toString(); }
  @Override public String submit(Segment s,String key)throws Exception { JSONObject o=new JSONObject(); o.put("index",s.index());o.put("model",s.model());o.put("prompt",s.prompt());o.put("referenceImages",new JSONArray(s.originalRefs()));o.put("params",params(s.originalParams())); JSONObject r=json("POST","/jobs",o,key,true); return requiredId(r,"id"); }
  @Override public PollResult poll(String id)throws Exception { pause(); validId(id); JSONObject r=json("GET","/jobs/"+URLEncoder.encode(id,"UTF-8"),null,null,true); String raw=r.optString("status","").toLowerCase(Locale.ROOT); Status st=switch(raw){case "queued"->Status.QUEUED;case "running"->Status.RUNNING;case "succeeded"->Status.SUCCEEDED;case "failed"->Status.FAILED;case "cancelled"->Status.CANCELLED;default->throw new IOException("gateway returned invalid status");}; String u=r.optString("resultUrl",null);if(u!=null&&!u.trim().isEmpty()) checkedUrl(u,false); return new PollResult(st,u,"provider reported "+raw); }
  @Override public String uploadReference(Path jpg)throws Exception { if(!Files.isRegularFile(jpg)||Files.size(jpg)>20*1024*1024) throw new IOException("reference JPEG is missing or too large"); HttpURLConnection c=open("/references",true);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","image/jpeg"); try{try(OutputStream out=c.getOutputStream();InputStream in=Files.newInputStream(jpg)){copy(in,out,20*1024*1024);} JSONObject r=response(c,MAX_JSON);String ref=r.optString("refUrl",r.optString("id","")); if(ref.trim().isEmpty())throw new IOException("gateway reference response lacks refUrl/id"); if(ref.startsWith("https://")) sameOrigin(ref); else validId(ref); return ref; }finally{c.disconnect();} }
  @Override public void download(String u,Path dest)throws Exception { URL target=checkedUrl(u,false); HttpURLConnection c=(HttpURLConnection)target.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(CONNECT_MS);c.setReadTimeout(READ_MS); if(same(target,origin)) auth(c);try{int code=c.getResponseCode();if(code<200||code>=300)throw new IOException("download HTTP "+code);long len=c.getContentLengthLong();if(len>MAX_DOWNLOAD)throw new IOException("result too large");Files.createDirectories(dest.getParent());Path tmp=dest.resolveSibling(dest.getFileName()+".tmp");long n=0;try(InputStream in=c.getInputStream();OutputStream out=Files.newOutputStream(tmp)){copy(in,out,MAX_DOWNLOAD);}catch(Exception e){Files.deleteIfExists(tmp);throw e;}finally{c.disconnect();}Files.move(tmp,dest,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE); }finally{c.disconnect();} }
  private JSONObject json(String method,String path,JSONObject body,String key,boolean gatewayOnly)throws Exception{HttpURLConnection c=open(path,gatewayOnly);c.setRequestMethod(method);if(key!=null)c.setRequestProperty("Idempotency-Key",key);if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=utf-8");try(OutputStream x=c.getOutputStream()){x.write(body.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}}try{return response(c,MAX_JSON);}finally{c.disconnect();}}
  private HttpURLConnection open(String path,boolean authed)throws Exception{guard();HttpURLConnection c=(HttpURLConnection)new URL(origin,path).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(CONNECT_MS);c.setReadTimeout(READ_MS);if(authed)auth(c);return c;} private void auth(HttpURLConnection c){if(!token.trim().isEmpty())c.setRequestProperty("Authorization","Bearer "+token);}
  private JSONObject response(HttpURLConnection c,int max)throws Exception{int code=c.getResponseCode();InputStream in=code>=200&&code<300?c.getInputStream():c.getErrorStream();String s=read(in,max);if(code<200||code>=300)throw new IOException("gateway HTTP "+code);try{return new JSONObject(s);}catch(Exception e){throw new IOException("gateway returned invalid JSON",e);}}
  private String read(InputStream in,int max)throws IOException{if(in==null)return "";try(in){ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] x=new byte[4096];for(int n;(n=in.read(x))>=0;){guard();if(b.size()+n>max)throw new IOException("response too large");b.write(x,0,n);}return new String(b.toByteArray(), java.nio.charset.StandardCharsets.UTF_8);}}
  private JSONObject params(Map<String,String> m)throws Exception { JSONObject o=new JSONObject(); for(var e:m.entrySet())o.put(e.getKey(),new JSONTokener(e.getValue()).nextValue()); return o; } private void pause() throws Exception { for(int i=0;i<30;i++){guard();Thread.sleep(100);} } private void guard() throws IOException { if(cancelled.getAsBoolean())throw new IOException("cancelled");if(System.currentTimeMillis()>deadline)throw new IOException("gateway deadline exceeded"); } private long copy(InputStream in,OutputStream out,long max)throws IOException{long n=0;byte[] b=new byte[8192];for(int z;(z=in.read(b))>=0;){guard();n+=z;if(n>max)throw new IOException("body too large");out.write(b,0,z);}return n;} private static URL origin(String x)throws Exception{URL u=checkedUrl(x,true);if(!u.getPath().equals("/")&&!u.getPath().isEmpty()||u.getQuery()!=null||u.getRef()!=null)throw new IllegalArgumentException("gateway must be an HTTPS origin only");return new URL(u.getProtocol(),u.getHost(),u.getPort(),"/");} private static URL checkedUrl(String x,boolean https)throws Exception{URL u=new URL(x);if(!"https".equalsIgnoreCase(u.getProtocol())||u.getUserInfo()!=null||u.getHost()==null)throw new IllegalArgumentException("HTTPS URL required");return u;} private void sameOrigin(String s)throws Exception{if(!same(checkedUrl(s,false),origin))throw new IOException("reference URL is outside configured gateway");} private static boolean same(URL a,URL b){return a.getProtocol().equalsIgnoreCase(b.getProtocol())&&a.getHost().equalsIgnoreCase(b.getHost())&&a.getPort()==b.getPort();} private static String requiredId(JSONObject o,String n)throws IOException{String id=o.optString(n,"");validId(id);return id;} private static void validId(String s)throws IOException{if(s==null||!s.matches("[A-Za-z0-9._:-]{1,200}"))throw new IOException("invalid gateway id");}
}





